#[derive(Debug)]pub struct Gpu{pub width:usize,pub height:usize,rgba:Vec<u8>}
impl Gpu{pub fn new(width:usize,height:usize)->Result<Self,&'static str>{let len=width.checked_mul(height).and_then(|v|v.checked_mul(4)).ok_or("framebuffer overflow")?;if len>64*1024*1024{return Err("framebuffer too large")}Ok(Self{width,height,rgba:vec![0;len]})}pub fn clear(&mut self,color:[u8;4]){for p in self.rgba.chunks_exact_mut(4){p.copy_from_slice(&color)}}pub fn framebuffer(&self)->&[u8]{&self.rgba}}
